312  void NcpBase::HandleReceive(const uint8_t *aBuf, uint16_t aBufLength)
   313  {
   314      otError      error  = OT_ERROR_NONE;
   315      uint8_t      header = 0;
   316      spinel_tid_t tid    = 0;
   317
   318      mDisableStreamWrite = true;
   319
   320      // Initialize the decoder with the newly received spinel frame.
   321      mDecoder.Init(aBuf, aBufLength);
   322
   323      // Receiving any message from the host has the side effect of transitioning the host power state to online.
   324      mHostPowerState           = SPINEL_HOST_POWER_STATE_ONLINE;
   325      mHostPowerStateInProgress = false;
   326
   327      // Skip if there is no header byte to read or this isn't a spinel frame.
   328
   329      SuccessOrExit(mDecoder.ReadUint8(header));
   330      VerifyOrExit((SPINEL_HEADER_FLAG & header) == SPINEL_HEADER_FLAG);
   331
   332      mRxSpinelFrameCounter++;
   333
   334      // We only support IID zero for now.
   335      if (SPINEL_HEADER_GET_IID(header) != 0)
   336      {
   337          WriteLastStatusFrame(header, SPINEL_STATUS_INVALID_INTERFACE);
   338          ExitNow();
   339      }
   340
   341      error = HandleCommand(header);
   342
   343      if (error != OT_ERROR_NONE)
   344      {
   345          PrepareLastStatusResponse(header, ThreadErrorToSpinelStatus(error));
   346      }
   347
   348      if (!IsResponseQueueEmpty())
   349      {
   350          // A response may have been prepared and queued for this command,
   351          // so we attempt to send/write any queued responses. Note that
   352          // if the response was prepared but cannot be sent now (not
   353          // enough buffer space available), it will be attempted again
   354          // from `HandleFrameRemovedFromNcpBuffer()` when buffer space
   355          // becomes available.
   356
   357          IgnoreReturnValue(SendQueuedResponses());
   358      }
   359
   360      // Check for out of sequence TIDs and update `mNextExpectedTid`,
   361
   362      tid = SPINEL_HEADER_GET_TID(header);
   363
   364      if ((mNextExpectedTid != 0) && (tid != mNextExpectedTid))
   365      {
   366          mRxSpinelOutOfOrderTidCounter++;
   367      }
   368
   369      mNextExpectedTid = SPINEL_GET_NEXT_TID(tid);
   370
   371  exit:
   372      mDisableStreamWrite = false;
   373  }
